{"code": "import os
import sys

hermes_dir = os.path.join(os.path.expanduser('~'), '.hermes')
mempalace_dir = os.path.join(hermes_dir, 'mempalace')
init_file = os.path.join(mempalace_dir, '__init__.py')

with open(init_file, 'r') as f:
    lines = f.readlines()

# Check for the import
import_line = None
for i, line in enumerate(lines):
    if 'from datetime import datetime' in line:
        import_line = i+1
        break

print(f"Import line: {import_line}")
if import_line:
    print(f"Line content: {lines[import_line-1].rstrip()}")

# Also check if there is any other import of datetime
for i, line in enumerate(lines):
    if 'import datetime' in line and not line.strip().startswith('#'):
        print(f"Alternative import at line {i+1}: {line.rstrip()}")"}
